llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C41"],
      "claim": "Bumetanide, a sulfamoyl-benzoic acid loop diuretic sharing the key acidic/sulfamoyl anthranilate pharmacophore with the query, has absolute oral bioavailability of 0.90 in normal subjects, demonstrating that this structural class can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Tolfenamic acid, an anthranilic acid with a free carboxyl and lipophilic N-aryl substituent, has absolute oral bioavailability of 63.2% in healthy volunteers, supporting high oral bioavailability for the query's anthranilic acid core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Hydrochlorothiazide, a sulfonamide-containing diuretic, has absolute oral bioavailability of 60.2% in humans, indicating that sulfonamide diuretics commonly exceed the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Azosemide, a close furosemide analog with tetrazole replacing the carboxyl and thiophene replacing furan, has low oral bioavailability (~10%) in patients, providing the strongest structural counterexample; however, its different acid bioisostere and reported high first-pass metabolism limit direct transfer to furosemide.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Although the closest direct analog azosemide is low, its tetrazole/thiophene modifications and high first-pass metabolism reduce transferability. Direct absolute-F data for structurally related sulfamoyl/anthranilic acid drugs (bumetanide 0.90, tolfenamic acid 63%, HCTZ 60%) consistently support F≥20%, and furosemide itself is clinically characterized by moderate oral bioavailability (~60%). Therefore high is predicted.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability record for furosemide parent is present in the provided evidence; the only furosemide-containing record is for its acyl glucuronide metabolite.",
    "Azosemide, the closest direct analog, has conflicting low values (10% and ~20.4%) and may differ in absorption/metabolism due to tetrazole and thiophene substitutions.",
    "Human furosemide bioavailability is variable; classification near the 20% threshold may depend on formulation and fasting state."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

